#!/usr/bin/env python3
"""Cumulative bibliography continuation v4: publisher, institutional and scholarly evidence.
Never asserts absence or full source-edition alignment merely from a title match.
"""
import csv,json,pathlib,collections
P=pathlib.Path(__file__).resolve().parent
C=P/'burn_research.csv';E=P/'translation_editions.jsonl';L=P/'manual_leads_and_exceptions.jsonl'
with C.open(newline='',encoding='utf8') as f:
 reader=csv.DictReader(f);fields=reader.fieldnames;rows=list(reader)
with E.open(encoding='utf8') as f: editions=[json.loads(s) for s in f if s.strip()]
with L.open(encoding='utf8') as f: leads=[json.loads(s) for s in f if s.strip()]
origpos={r['catalog'] for r in rows if r['has_translation']=='TRUE'}
origkeys={(e['catalog'],e['translator'],e['year'],e['scope'],e['info_url']) for e in editions}
byid={r['catalog']:r for r in rows if r['catalog']}
RESEARCHER='ChatGPT manual bibliography research, continuation v4'
def add(cid,translator,year,scope,url,publisher,language='en',evidence='',corroboration='',access='BUY',confidence='high',source='publisher_catalogue',download=''):
 assert cid in byid,cid
 assert url.startswith('https://'),url
 r=byid[cid]
 k=(cid,translator,str(year),scope,url)
 if k in origkeys:return
 origkeys.add(k)
 ed={'access_mode': 'ONLINE_HTML' if access=='HTML' else ('ONLINE_PDF' if access=='PDF' else access), 'access_tier': 'DIRECT' if download else ('' if access in ('HTML','PDF') else access), 'catalog':cid,'confidence':confidence,'corroboration_url':corroboration,'download_url':download,'evidence':evidence,'info_url':url,'language':language,'publication_status':'published','publisher':publisher,'researcher':RESEARCHER,'scope':scope,'source_type':source,'title':r['title'],'translator':translator,'verification_status':'BIBLIOGRAPHICALLY_VERIFIED','verified_at':'2026-11-11','year':str(year)}
 editions.append(ed)
 if r['has_translation']!='TRUE':
  assert not any(r[z] for z in ['translator','year','scope_full_partial_chapters','info_url']),cid
  r.update(has_translation='TRUE',translator=translator,year=str(year),scope_full_partial_chapters=scope,access_tier=ed['access_tier'],download_url=download,publisher=publisher,info_url=url,evidence_notes=evidence+' [Additional editions in translation_editions.jsonl; source text collation may be needed.]',researcher=RESEARCHER,verified_at='2026-11-11')
def lead(cid,status,note,urls):
 assert cid in byid
 if any(x.get('catalog')==cid and x.get('status')==status for x in leads):return
 leads.append({'catalog':cid,'title':byid[cid]['title'],'status':status,'note':note,'links':urls})

